const item = String(query || "").toLowerCase().trim();

let category;
let bin;
let reason;

// 1. Hazardous waste: dangerous materials and substances
if (/toxic|corrosive|flammable chemical|industrial chemical|chemical waste|pesticide|poison|solvent waste|hazardous|infectious waste|chemical sludge|contaminated chemical/.test(item)) {
category = "Hazardous Waste";
bin = "Authorised Hazardous Waste Collection";
reason = "The described material may contain dangerous substances and requires specialised handling.";

// 2. E-waste
} else if (/mobile|smartphone|laptop|computer|charger|cable|keyboard|mouse|television|electronic|earphone|headphone|circuit board|electronic component/.test(item)) {
category = "E-waste";
bin = "E-waste Collection Bin";
reason = "This contains electronic components and should go to an authorised e-waste recycler.";

// 3. Wet waste: biodegradable organic materials
} else if (/cucumber|vegetable|fruit|banana|apple|orange|potato|tomato|onion|carrot|cabbage|spinach|food|food scraps|food waste|peel|leaves|tea|coffee|eggshell|leftover|organic|flowers|garden waste|plant waste/.test(item)) {
category = "Wet Waste";
bin = "Green Bin";
reason = "This is biodegradable organic material suitable for composting.";

// 4. Dry waste: identifiable recyclable materials
} else if (/plastic|paper|cardboard|glass bottle|metal can|aluminium|aluminum|tin can|newspaper|packaging|carton|rubber|fabric|textile/.test(item)) {
category = "Dry Waste";
bin = "Blue Bin";
reason = "This is generally a recyclable or non-biodegradable material. Check that it is not contaminated.";

// 5. Uncertain or unfamiliar materials
} else {
return "Item: ${query} CATEGORY: Needs Further Identification Reason: The material cannot be reliably classified from the available description. Recommended Disposal Method: Do not assume it is dry waste. Identify its composition and properties first. Safety Advice: If it may contain chemicals, toxins or other dangerous substances, keep it separate until identified.";
}

return "Item: ${query} CATEGORY: ${category} Recommended Disposal Bin: ${bin} Reason: ${reason} Safety Advice: Follow local waste segregation and disposal guidelines.";
